const EFFECT=[['ダメージ','を任意のプレイヤーに与える'],['ダメージ','を他のプレイヤー全員に与える'],['ポイント分','、自分の体力を増やす'],null,['枚のカード','を山札からドローする'],['枚ずつ','、全プレイヤーが山札からドローする'],['枚まで','、自分の手札からカードを捨てる'],['枚のカード','を任意のプレイヤーの手札からランダムに捨てる'],['つの','アクション権を獲得する'],null,null,['枚のカード','を自分の手札から任意のプレイヤーに渡す'],null,['回','、ランダムな効果を発動する']];
const countEffects=c=>c.kind==='action'?c.e.reduce((sum,e)=>sum+e.n,0):0;
const level=c=>{const n=c.kind==='action'?c.t.length+countEffects(c):0;return n<=2?0:n<=4?1:n<=6?2:3};
const effectParts=(id,n=1)=>{const e=EFFECT[id];if(!e)return ['',({3:'任意のプレイヤーと体力を交換する',9:'発動後に墓地へ行かず、手札に残る',10:'前回発動したカードの効果を発動する',12:'墓地のカードをすべて山札に戻し、シャッフルする'})[id]??labelsE[id]];return [n+e[0],e[1]]};
function cardHTML(c,{large=false,mini=false,progress=null,trigger=null,footer='',showId=true}={}){
 const ev=c.kind==='event',count=ev?0:countEffects(c),lv=level(c),id=showId&&c.id!=null?'#'+c.id:'';
 const top=`<div class="card-top">${ev?`<span>EVENT ${id}</span>`:`<span class="card-level">T${c.t.length}/E${count}</span><span>ACTION ${id} ${'◆'.repeat(lv+1)}</span>`}</div>`;
 const mods=ev?`<div class="module event-mod ${progress?'current':''}">${esc(V[c.event])}</div><div class="module event-mod">${esc(EVENT_DESCS[c.event])}</div>`:`<div class="card-heading">トリガー</div><div class="modules">${c.t.map(t=>`<div class="module ${TC[t]} ${trigger===t?'triggered':''}">${esc(TRIGGER[t])}</div>`).join('')}</div><div class="card-heading">効果</div><div class="modules">${c.e.map(({id,n},i)=>{const [q,l]=effectParts(id,n);return `<div class="module ${EC[id]} ${progress?.[0]?.kind==='line'&&progress[0].index===i?'current':''}">${q?`<span class="quantity">${esc(q)}</span>`:''}${esc(l)}</div>`}).join('')}</div>`;
 return `<div data-card-model="${esc(JSON.stringify({c,trigger,progress,footer,showId}))}" class="card ${ev?'event':'level-'+lv} ${large?'card-large':''} ${mini?'card-mini':''}">${top}${mods}${footer?`<div class="card-footer">${esc(footer)}</div>`:''}</div>`;
}
const clone=x=>JSON.parse(JSON.stringify(x));
