function seating(){const list=g.seats,at=list.indexOf(viewId),rx=portrait.matches?36.5:41,ry=portrait.matches?36.5:38;return list.map((id,i)=>{const j=(i-at+list.length)%list.length,a=j*Math.PI*2/list.length;return {id,x:50-rx*Math.sin(a),y:50+ry*Math.cos(a),a}})}
