function renderVote(){const c=choice;openModal(name(c.id)+'：ベストカード投票',`<p>最終デッキから好きな基準で1枚選びます。他プレイヤーの投票先は結果発表まで非公開です。</p><div class="row"><select id="vote-type" aria-label="カード種類"><option value="all">全カード</option><option value="action">アクション</option><option value="event">イベント</option></select><select id="vote-trigger" aria-label="トリガーで絞り込み"><option value="all">全トリガー</option>${TRIGGER.map((t,i)=>`<option value="${i}">${esc(t)}</option>`).join('')}</select><select id="vote-effect" aria-label="効果で絞り込み"><option value="all">全効果</option>${labelsE.map((t,i)=>`<option value="${i}">${esc(t)}</option>`).join('')}</select><select id="vote-sort" aria-label="並べ替え"><option value="complex">構成数順</option><option value="id">カード番号順</option></select></div><div id="vote-collection" class="vote-collection"></div><p id="vote-selected" class="muted" aria-live="polite">${c.selected?'選択中：#'+c.selected.v.id:'1枚選択してください'}</p><div id="vote-detail" hidden></div>`,`<button data-dialog="voteDetail" ${c.selected?'':'disabled'}>詳細</button><button class="primary" data-dialog="choiceConfirm" ${c.selected?'':'disabled'}>投票する</button>`,{kind:'choice',wide:true,closable:false});
 const draw=()=>{const type=$('vote-type').value,tr=$('vote-trigger').value,ef=$('vote-effect').value,sort=$('vote-sort').value;let list=c.opts.map((o,i)=>({o,i})).filter(({o})=>{const card=o.v;return(type==='all'||card.kind===type)&&(tr==='all'||card.t?.includes(+tr))&&(ef==='all'||card.e?.some(e=>e.id===+ef))});list.sort((a,b)=>sort==='id'?a.o.v.id-b.o.v.id:((b.o.v.t?.length??0)+countEffects(b.o.v))-((a.o.v.t?.length??0)+countEffects(a.o.v))||a.o.v.id-b.o.v.id);$('vote-collection').innerHTML=list.map(({o,i})=>`<button data-opt="${i}" class="${c.selected===o?'chosen':''}" aria-pressed="${c.selected===o}">${cardHTML(o.v,{mini:true})}</button>`).join('')||'<p class="muted">該当カードなし</p>'};['vote-type','vote-trigger','vote-effect','vote-sort'].forEach(id=>$(id).onchange=draw);draw()}
function flow(open){return new Promise(resolve=>{flowResume=()=>{flowResume=null;resolve()};const run=()=>{if(abort){flowResume?.();return}open()};if(modalKind==='aux')queuedFlow=run;else run()})}
function finishFlow(){const done=flowResume;flowResume=null;closeModal(false);done?.()}
async function scoreFlow(before){await flow(()=>{const oldOrder=[...g.p].sort((a,b)=>before[b.id]-before[a.id]||g.seats.indexOf(a.id)-g.seats.indexOf(b.id));const winner=g.p.slice().sort((a,b)=>b.lastRank-a.lastRank)[0];const rows=oldOrder.map((p,i)=>`<div class="score-row" id="score-${p.id}"><span class="place">${i+1}</span>${orb(p.id)}<strong>${name(p.id)} <small>${g.p.length-p.lastRank}位</small></strong><span class="gain">+0</span><span class="bonus">+0</span><span class="score-total">${before[p.id]}</span></div>`).join('');openModal(`ROUND ${g.round} COMPLETE`,`<p>${name(winner.id)} が最後まで生存しました。</p><div class="scoreboard" id="scoreboard"><div class="score-row header"><span>順位</span><span></span><span>プレイヤー</span><span>生存点</span><span>能力点</span><span>累計</span></div>${rows}</div>`,`<button class="primary" data-dialog="flowDone" disabled>次へ</button>`,{kind:'flow',closable:false});animateScores(oldOrder,before)});checkAbort()}
async function animateScores(order,before){const match=g;await speedWait(1000);if(g!==match||modalKind!=='flow'||!$('scoreboard'))return;const animate=async(key,cls)=>{const max=Math.max(...order.map(p=>p.roundScores.at(-1)?.[key]??0));for(let i=1;i<=max;i++){for(const p of order){const r=$('score-'+p.id);if(!r)return;const n=Math.min(i,p.roundScores.at(-1)[key]);r.querySelector(cls).textContent='+'+n;r.querySelector('.score-total').textContent=before[p.id]+(key==='bonus'?p.roundScores.at(-1).survival:0)+n}await speedWait(250)}};await animate('survival','.gain');await speedWait(1000);await animate('bonus','.bonus');if(! $('scoreboard')||g!==match)return;const positions=new Map(order.map(p=>[p.id,$('score-'+p.id).getBoundingClientRect().top]));const sorted=[...g.p].sort((a,b)=>b.score-a.score||before[b.id]-before[a.id]||g.seats.indexOf(a.id)-g.seats.indexOf(b.id));for(const [i,p] of sorted.entries()){const r=$('score-'+p.id);if(!r)return;$('scoreboard').append(r);r.querySelector('.place').textContent=i+1;r.querySelector('.score-total').textContent=p.score;if(i===0)r.classList.add('winner')}
 await presentation.scoreRows(sorted,positions);await speedWait(1000);const b=layer.querySelector('[data-dialog="flowDone"]');if(b)b.disabled=false}
async function generatedFlow(p,c){renderGame();await flow(()=>{openModal(name(p.id)+' がカードを生成',cardHTML(c,{large:true})+'<p class="muted" style="text-align:center">共通デッキに追加しました</p>','',{kind:'flow',closable:false});speedWait(1000).then(()=>{if(modalKind==='flow'&&flowResume)finishFlow()})});checkAbort()}
async function voteResultsFlow(results){if(!results.length)return;await flow(()=>{openModal('BEST CARD · 投票結果',`<p class="muted">得票カードと最多変更者に与えられたポイント</p><div id="vote-results" style="display:grid;gap:10px"></div>`,`<button class="primary" data-dialog="flowDone" disabled>次へ</button>`,{kind:'flow',wide:true,closable:false});revealVotes(results)});checkAbort()}
async function revealVotes(results){const max=results[0].count;for(const r of results){if(!$('vote-results')||abort)return;const entry=document.createElement('div');entry.className='vote-result '+(r.count===max?'best':'');entry.innerHTML=`${cardHTML(r.card,{mini:true})}<div class="contributions"><span class="votes">${r.count} VOTE${r.count!==1?'S':''}${r.count===max?' · BEST':''}</span>${g.p.filter(p=>(r.card.changes?.[p.id]??0)>0).sort((a,b)=>(r.card.changes[b.id]??0)-(r.card.changes[a.id]??0)).map(p=>`<div class="contribution"><span class="row">${orb(p.id)} ${name(p.id)}</span><span>変更 ${r.card.changes[p.id]}回</span>${r.recipients.includes(p.id)?`<span class="plus">+${r.count}pt</span>`:''}</div>`).join('')||'<small>未変更カード：加点なし</small>'}</div>`;$('vote-results').append(entry);presentation.invalidate();await speedWait(1000)}const b=layer.querySelector('[data-dialog="flowDone"]');if(b)b.disabled=false}
function renderResult(){const standings=g.standings(),w=standings[0];app.innerHTML=`<div class="topbar"><span class="brand">Bless Us</span><span class="tag">GAME COMPLETE</span></div><main class="result-panel"><section class="winner-hero celebrate" id="winner-hero"><span class="spark s1">${icon('star')}</span><span class="spark s2">${icon('star')}</span><span class="crown">${icon('trophy')}</span>${orb(w.id)}<h1>${name(w.id)} WINS!</h1><strong>${w.score} POINTS</strong></section><section class="panel" id="result-scores" hidden><h2 style="margin-bottom:12px">最終戦績</h2><div class="results-wrap"><table class="results-table"><thead><tr><th>順位</th><th>プレイヤー</th>${Array.from({length:g.round},(_,i)=>`<th>R${i+1}</th>`).join('')}<th>投票</th><th>累計</th><th>最終生存順位</th></tr></thead><tbody>${standings.map((p,i)=>`<tr><td>${i+1}</td><td><span class="result-name">${orb(p.id)} ${name(p.id)} ${isCpu(p.id)?'<small>CPU</small>':''}</span></td>${p.roundScores.map(s=>`<td>${s.total}</td>`).join('')}<td>${p.voteScore}</td><td><strong>${p.score}</strong></td><td>${g.p.length-p.lastRank}位</td></tr>`).join('')}</tbody></table></div><p class="muted" style="margin-top:10px;font-size:.82rem">同点の場合は、最終ラウンドの生存順位で順位を決定します。</p></section><div class="row spread" id="result-actions" hidden>${actionButton('検証ログを保存','download','quiet')}${actionButton('ルームへ戻る','resultRoom','primary')}</div></main>`;const match=g;setTimeout(()=>{if(page!=='result'||g!==match)return;const hero=$('winner-hero');presentation.winner(w.id).then(()=>{if(page!=='result'||g!==match)return;hero.classList.remove('celebrate');$('result-scores').hidden=false;$('result-actions').hidden=false;presentation.invalidate()})},settings.reduced?0:1000/settings.speed)}
function showGrave(){if(!g)return;const waiting=new Set(g.pendingCards().map(c=>c.id));openModal('墓地 · '+g.grave.length+'枚',`<div class="vote-collection">${g.grave.map(c=>`<div class="${waiting.has(c.id)?'grave-waiting':''}">${cardHTML(c,{mini:true,footer:waiting.has(c.id)?'発動待機中':''})}</div>`).join('')||'<p>墓地は空です。</p>'}</div>`,'<button data-dialog="close">閉じる</button>',{wide:true})}
function showLog(){if(!g)return;openModal('ラウンドログ',`<div class="log-toolbar"><span class="tag">ROUND ${g.round}</span><select id="log-filter" aria-label="ログ絞り込み"><option value="all">すべて</option><option value="card">カード・能力発動</option><option value="hp">体力変動・脱落</option></select></div><div id="log-wrap" class="log-wrap"></div>`,'<button data-dialog="close">閉じる</button>',{wide:true});$('log-filter').onchange=renderLog;renderLog()}
function renderLog(){const wrap=$('log-wrap');if(!wrap||!g)return;const filter=$('log-filter').value,entries=g.timeline.map((x,i)=>({...x,index:i+1})).filter(x=>x.round===g.round&&(filter==='all'||filter==='card'&&x.root||filter==='hp'&&(/HP|脱落/.test(x.text))));const acts=new Map(g.activations.map(a=>[a.seq,a]));wrap.innerHTML='<svg class="log-tree" id="log-tree" aria-hidden="true"></svg>'+entries.map(e=>{const a=acts.get(e.activation);return `<div class="log-entry ${e.root?'root':''}" data-seq="${e.index}" data-act="${e.activation??''}" data-root="${e.root?'1':'0'}"><span class="seq">${String(e.index).padStart(3,'0')}</span><div class="log-content">${e.root&&a?`<details><summary>${esc(e.text)}${a.card?' #'+a.card.id:''} · T${e.turn}${a.cause?' ← #'+(acts.get(a.cause)?.card?.id??a.cause):''}</summary>${a.card?cardHTML(a.card,{mini:true}):esc(a.label)}<p>${a.steps?.map(s=>esc(progressText(s))).join('<br>')??''}</p></details>`:esc(e.text)}</div></div>`}).join('');if(!entries.length)wrap.innerHTML='<p class="muted">該当ログなし</p>';else{wrap.querySelectorAll('details').forEach(el=>el.addEventListener('toggle',drawLogTree));drawLogTree()}}
function drawLogTree(){const wrap=$('log-wrap'),svg=$('log-tree');if(!wrap||!svg)return;const rows=[...wrap.querySelectorAll('.log-entry')],rect=wrap.getBoundingClientRect(),acts=new Map(g.activations.map(a=>[a.seq,a])),roots=new Map(),lane=new Map();for(const r of rows){const n=+r.dataset.act;if(r.dataset.root==='1')roots.set(n,r)}
 const colors=['#9471cb','#3983bc','#b68c24','#338b75','#c36d57'];let idx=0;const pos=r=>r.getBoundingClientRect().top-rect.top+14;for(const r of rows){const act=+r.dataset.act;if(act&&!lane.has(act))lane.set(act,(idx++%4)+1)}const x=act=>act?7+(lane.get(act)??0)*8:5;const lines=[];if(rows.length)lines.push(`<path d="M5 ${pos(rows[0])} V${pos(rows.at(-1))}" stroke="#d4c1e4" stroke-width="2" fill="none"/>`);for(const r of rows){const act=+r.dataset.act,y=pos(r),cx=x(act),a=acts.get(act),col=colors[(lane.get(act)??0)%colors.length];if(r.dataset.root==='1'&&a?.cause&&roots.has(a.cause)){const pr=roots.get(a.cause),py=pos(pr),px=x(a.cause);lines.push(`<path d="M${px} ${py} C${px} ${py+12} ${cx} ${y-12} ${cx} ${y}" stroke="${col}" stroke-width="1.8" fill="none"/>`)}else if(cx!==5)lines.push(`<path d="M5 ${y} H${cx}" stroke="${col}" stroke-width="1.3" fill="none"/>`);lines.push(`<circle cx="${cx}" cy="${y}" r="${r.dataset.root==='1'?4:2.6}" fill="${col}"/>`)}svg.setAttribute('viewBox',`0 0 66 ${Math.max(1,wrap.offsetHeight)}`);svg.setAttribute('preserveAspectRatio','none');svg.innerHTML=lines.join('')}
function showSettings(){openModal('設定',`<div class="settings-grid">${[['master','マスター音量'],['bgm','BGM'],['se','効果音']].map(([key,label])=>`<div class="settings-row"><label for="set-${key}">${label}</label><input id="set-${key}" type="range" min="0" max="100" value="${settings[key]}"><output id="out-${key}">${settings[key]}%</output></div>`).join('')}<div class="settings-row"><label for="set-speed">演出速度</label><select id="set-speed">${[.5,1,2,4].map(v=>`<option value="${v}" ${+settings.speed===v?'selected':''}>${v}×</option>`).join('')}</select></div>${[['shake','画面の揺れ'],['reduced','発光・演出を軽減'],['overlap','手札を重ねて表示']].map(([key,label])=>`<div class="settings-row"><label for="set-${key}">${label}</label><input type="checkbox" id="set-${key}" ${settings[key]?'checked':''}></div>`).join('')}</div>${page==='game'?`<hr><div class="row">${actionButton(paused?'CPUを再開':'CPUを一時停止','pauseCpu')}${actionButton('検証ログを保存','download')}${actionButton('対戦を中断','quit','danger')}</div>`:''}`, '<button class="primary" data-dialog="close">閉じる</button>');for(const key of ['master','bgm','se'])$('set-'+key).oninput=()=>{unlockAudio();settings[key]=+$('set-'+key).value;$('out-'+key).textContent=settings[key]+'%';applySettings();if(key==='se')sound()};$('set-speed').onchange=()=>{settings.speed=+$('set-speed').value;applySettings()};for(const key of ['shake','reduced','overlap'])$('set-'+key).onchange=()=>{settings[key]=$('set-'+key).checked;applySettings();if(page==='game')sizeHand()}}
function download(){if(!g)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(page==='result'?{config:g.cfg,seats:g.seats,modes:matchModes,round:g.round,players:g.p,deck:g.deck,grave:g.grave,history:g.history,log:g.log,votingResults:g.votingResults}:{round:g.round,log:g.timeline},null,2)],{type:'application/json'}));a.download='bless-us-'+g.cfg.seed+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
// Deck editor: identical initial cards are grouped, but persisted cards remain independent instances.
const keyOf=c=>c.kind==='event'?'v'+c.event:'t'+c.t[0]+'e'+c.e[0].id;
function draftFrom(id){const d=decks.find(d=>d.id===id);deckDraft=d?clone(d):{id:null,name:'新規デッキ',cards:standardCards()};deckFilter='all'}
function groups(){const out=new Map();for(const c of deckDraft.cards){const key=keyOf(c);if(!out.has(key))out.set(key,{key,c,n:0});out.get(key).n++}return [...out.values()].sort((a,b)=>a.c.kind.localeCompare(b.c.kind)||a.key.localeCompare(b.key,'ja',{numeric:true}))}
function rememberDeckName(){if($('deck-name'))deckDraft.name=$('deck-name').value}
function renderDeck(){if(!deckDraft)draftFrom(null);const good=deckValid(deckDraft.cards),events=V.map((_,i)=>deckDraft.cards.filter(c=>c.kind==='event'&&c.event===i).length);app.innerHTML=`${navTitle('デッキカスタマイズ','deckHome')}<main class="deck-page"><div class="panel"><div class="deck-toolbar"><div class="field"><label for="deck-load">保存済みデッキ (${decks.length}/100)</label><select id="deck-load"><option value="">新規／未保存</option>${decks.map(d=>`<option value="${esc(d.id)}" ${d.id===deckDraft.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></div><div class="field"><label for="deck-name">デッキ名</label><input id="deck-name" maxlength="80" value="${esc(deckDraft.name)}"></div>${actionButton('新規','newDeck')}${actionButton('複製','duplicateDeck')}${actionButton('削除','deleteDeck','danger')}</div><div class="row spread" style="margin-top:12px"><strong>${deckDraft.cards.length} / 60枚</strong><span class="deck-status ${good?'valid':'invalid'}">${good?'保存条件を満たしています':'40〜60枚・各イベント1枚以上が必要'}</span></div><small>${V.map((v,i)=>v+' '+events[i]).join(' / ')}</small></div><div class="row spread"><div class="row">${['all','action','event'].map((v,i)=>`<button data-filter="${v}" class="${deckFilter===v?'primary':''}">${['すべて','アクション','イベント'][i]}</button>`).join('')}</div>${actionButton('マトリクス','matrix')}</div><div class="collection">${groups().filter(x=>deckFilter==='all'||x.c.kind===deckFilter).map(({key,c,n})=>`<article class="collection-item">${cardHTML(c,{mini:true,showId:false})}<div class="collection-actions"><span class="count">×${n}</span><button data-deck-minus="${key}" aria-label="1枚削除">−</button><button data-deck-plus="${key}" aria-label="同じカードを1枚追加" ${deckDraft.cards.length>=60?'disabled':''}>＋</button><button data-deck-edit="${key}">変更</button></div></article>`).join('')||'<p class="muted">カードなし</p>'}</div><div class="deck-footer">${actionButton('＋ アクション','addAction')}${actionButton('＋ イベント','addEvent')}${actionButton('標準に戻す','resetDeck')}${actionButton('保存','saveDeck','primary')}</div></main>`;$('deck-load').onchange=()=>{const id=$('deck-load').value;draftFrom(id);renderDeck()};app.querySelector('[data-action="deleteDeck"]').disabled=!deckDraft.id;app.querySelector('[data-action="saveDeck"]').disabled=!good}
function addCards(c,n){if(deckDraft.cards.length+n>60){toast('60枚を超えることはできません');return false}for(let i=0;i<n;i++)deckDraft.cards.push(clone(c));return true}
function workshop(kind,key=null){rememberDeckName();const group=key?groups().find(x=>x.key===key):null,orig=group?.c;openModal(kind==='action'?'アクションカード '+(key?'変更':'追加'):'イベントカード '+(key?'変更':'追加'),`<div class="room-settings" style="grid-template-columns:${kind==='action'?'repeat(2,minmax(0,1fr))':'1fr'}">${kind==='action'?`<div class="field"><label for="work-t">トリガー</label><select id="work-t">${TRIGGER.map((t,i)=>`<option value="${i}" ${orig?.t?.[0]===i?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label for="work-e">効果</label><select id="work-e">${labelsE.map((e,i)=>`<option value="${i}" ${orig?.e?.[0]?.id===i?'selected':''}>${esc(e)}</option>`).join('')}</select></div>`:`<div class="field"><label for="work-v">イベント</label><select id="work-v">${V.map((v,i)=>`<option value="${i}" ${orig?.event===i?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`}</div><div id="work-preview"></div><div class="field"><label for="work-n">${key?'変更':'追加'}する枚数</label><input id="work-n" type="number" min="1" max="${key?group.n:Math.max(1,60-deckDraft.cards.length)}" value="1"></div>`,`<button data-dialog="close">戻る</button><button id="work-confirm" class="primary">${key?'変更':'追加'}を確定</button>`);const current=()=>kind==='action'?{kind:'action',t:[+$('work-t').value],e:[{id:+$('work-e').value,n:1}]}:{kind:'event',event:+$('work-v').value};const preview=()=>{$('work-preview').innerHTML=cardHTML(current(),{large:true,showId:false})};layer.querySelectorAll('select').forEach(el=>el.onchange=preview);preview();$('work-confirm').onclick=()=>{const n=+$('work-n').value;if(!Number.isInteger(n)||n<1||n>(key?group.n:60-deckDraft.cards.length)){toast('枚数を確認してください');return}const c=current();if(key){let left=n;deckDraft.cards=deckDraft.cards.map(old=>left>0&&keyOf(old)===key?(left--,clone(c)):old)}else if(!addCards(c,n))return;closeModal(false);renderDeck()}}
function matrix(){rememberDeckName();openModal('初期デッキ構成マトリクス',`<div class="row"><label><input id="matrix-empty" type="checkbox"> 空行・空列を非表示</label></div><div class="matrix-scroll" id="matrix-scroll"></div><small>イベント：${V.map((v,i)=>`${v} ${deckDraft.cards.filter(c=>c.kind==='event'&&c.event===i).length}枚`).join(' / ')}</small>`,'<button data-dialog="close">閉じる</button>',{wide:true});const draw=()=>{const grid=TRIGGER.map((_,t)=>E.map((_,e)=>deckDraft.cards.filter(c=>c.kind==='action'&&c.t[0]===t&&c.e[0].id===e).length)),hide=$('matrix-empty').checked,rs=grid.map((_,i)=>i).filter(i=>!hide||grid[i].some(Boolean)),cs=E.map((_,i)=>i).filter(i=>!hide||grid.some(row=>row[i]>0));$('matrix-scroll').innerHTML=`<table class="matrix"><thead><tr><th>トリガー＼効果</th>${cs.map(i=>`<th>${esc(E[i])}</th>`).join('')}</tr></thead><tbody>${rs.map(t=>`<tr><td>${esc(TRIGGER[t])}</td>${cs.map(e=>`<td class="${grid[t][e]?'nonzero':''}" style="--n:${Math.min(12,grid[t][e])}">${grid[t][e]||'–'}</td>`).join('')}</tr>`).join('')}</tbody></table>`};$('matrix-empty').onchange=draw;draw()}
function saveDeck(){rememberDeckName();if(!deckValid(deckDraft.cards)||!deckDraft.name.trim()){toast('名前とデッキの構成を確認してください。');return}const copy=clone(deckDraft);copy.name=copy.name.trim();if(!copy.id){if(decks.length>=100){toast('保存上限は100個です');return}copy.id=crypto.randomUUID?.()??String(Date.now());}const next=[...decks.filter(d=>d.id!==copy.id),copy];if(!writeSaved('bless-us-decks-v1',next)){toast('端末への保存に失敗しました');return}decks=next;deckDraft=clone(copy);toast('デッキを保存しました');renderDeck()}
function pauseCpu(){paused=!paused;if(!paused){for(const c of [...pendingChoices.values()])if(isCpu(c.id)){pendingChoices.delete(c.id);c.resolve(bot(c.id,c.prompt,c.opts))}if(choice&&!pendingChoices.has(choice.id))choice=pendingChoices.values().next().value??null;}if(modalKind==='aux')closeModal(true);else{renderGame();schedule()}}
function handleAction(id){switch(id){case'home':show('home');break;case'room':show('room');break;case'deck':draftFrom(null);show('deck');break;case'deckHome':deckDraft=null;show('home');break;case'settings':showSettings();break;case'addHuman':case'addCpu':rememberRoom();if(modes.length<6)modes.push(id==='addCpu'?'cpu':'human');renderRoom();break;case'newGame':startGame();break;case'nextRound':act(()=>g.startRound());break;case'endTurn':act(()=>g.endTurn());break;case'log':showLog();break;case'grave':showGrave();break;case'handDetail':if(selectedCard())cardDetail(selectedCard(),canPlay(selectedCard()));break;case'handUse':if(canPlay(selectedCard()))cardDetail(selectedCard(),true);break;case'confirmTarget':if(choice?.selected)accept(choice.selected);break;case'pauseCpu':pauseCpu();break;case'resumeCpu':if(paused)pauseCpu();break;case'quit':quitGame();break;case'download':download();break;case'resultRoom':g=null;show('room');break;case'newDeck':draftFrom(null);renderDeck();break;case'duplicateDeck':rememberDeckName();deckDraft={...clone(deckDraft),id:null,name:deckDraft.name+'（コピー）'};renderDeck();break;case'deleteDeck':if(deckDraft.id)confirmGame('この保存済みデッキを削除しますか？',()=>{const next=decks.filter(d=>d.id!==deckDraft.id);if(!writeSaved('bless-us-decks-v1',next)){toast('削除に失敗しました');return}if(room.deckId===deckDraft.id)room.deckId='default';decks=next;draftFrom(null);renderDeck()});break;case'resetDeck':rememberDeckName();confirmGame('編集中の構成を標準デッキに戻しますか？',()=>{deckDraft.cards=standardCards();renderDeck()});break;case'addAction':workshop('action');break;case'addEvent':workshop('event');break;case'matrix':matrix();break;case'saveDeck':saveDeck();break}}
app.addEventListener('click',e=>{unlockAudio();const sw=e.target.closest('[data-switch-choice]');if(sw){switchChoice(+sw.dataset.switchChoice);return}const button=e.target.closest('button');if(button?.disabled)return;const a=e.target.closest('[data-action]');if(a){handleAction(a.dataset.action);return}if(!g&&page==='game')return;if(e.target.closest('[data-ability]')){abilityDetail(+e.target.closest('[data-ability]').dataset.ability);return}if(e.target.closest('[data-abilities]')){abilityList(+e.target.closest('[data-abilities]').dataset.abilities);return}if(e.target.closest('[data-activation]')){const a=g.activations.find(x=>x.seq===+e.target.closest('[data-activation]').dataset.activation);if(a?.card)cardDetail(a.card);else if(a)openModal('発動したアビリティ',esc(a.label),'<button data-dialog="close">閉じる</button>');return}const seat=e.target.closest('[data-seat]');if(seat&&choiceKind()==='player'){const o=optionFor(+seat.dataset.seat);if(o){choice.selected=o;renderSeats();renderBanner()}return}
 if(e.target.closest('[data-accept]')){accept(choice?.opts[+e.target.closest('[data-accept]').dataset.accept]);return}if(page==='room'){if(button?.dataset.mode!=null){rememberRoom();const i=+button.dataset.mode;modes[i]=modes[i]==='cpu'?'human':'cpu';renderRoom()}else if(button?.dataset.remove!=null&&modes.length>2){rememberRoom();modes.splice(+button.dataset.remove,1);renderRoom()}}else if(page==='deck'&&button){rememberDeckName();if(button.dataset.filter){deckFilter=button.dataset.filter;renderDeck()}else if(button.dataset.deckPlus){const group=groups().find(x=>x.key===button.dataset.deckPlus);if(group&&addCards(group.c,1))renderDeck()}else if(button.dataset.deckMinus){const index=deckDraft.cards.findIndex(c=>keyOf(c)===button.dataset.deckMinus);if(index>=0){deckDraft.cards.splice(index,1);renderDeck()}}else if(button.dataset.deckEdit){const group=groups().find(x=>x.key===button.dataset.deckEdit);if(group)workshop(group.c.kind,group.key)}}});
app.addEventListener('keydown',e=>{const seat=e.target.closest('[data-seat]');if(seat&&(e.key==='Enter'||e.key===' ')&&choiceKind()==='player'){e.preventDefault();const o=optionFor(+seat.dataset.seat);if(o){choice.selected=o;renderSeats();renderBanner()}}});
app.addEventListener('pointerover',e=>{if(!hoverable.matches||e.pointerType!=='mouse')return;const b=e.target.closest('[data-ability]');if(b&&!b.contains(e.relatedTarget))tooltipHTML(`<div class="tip-text">${esc(AB_DESCS[+b.dataset.ability])}</div>`,b.getBoundingClientRect())});app.addEventListener('pointerout',e=>{if(e.target.closest('[data-ability]')&&!e.target.closest('[data-ability]').contains(e.relatedTarget))hideTip()});
let abilityHold=null;app.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-ability]');if(b&&e.pointerType!=='mouse'){clearTimeout(abilityHold);abilityHold=setTimeout(()=>abilityDetail(+b.dataset.ability),480)}});['pointerup','pointercancel','pointermove'].forEach(type=>app.addEventListener(type,()=>clearTimeout(abilityHold)));
layer.addEventListener('click',e=>{const sw=e.target.closest('[data-switch-choice]');if(sw){switchChoice(+sw.dataset.switchChoice);return}const target=e.target.closest('button');if(!target||target.disabled)return;unlockAudio();if(target.dataset.action){handleAction(target.dataset.action);return}if(target.dataset.opt!=null){if(voteHoldFired){voteHoldFired=false;return}selectChoice(+target.dataset.opt);return}if(target.dataset.accept!=null){accept(choice?.opts[+target.dataset.accept]);return}switch(target.dataset.dialog){case'close':closeAux();break;case'choiceConfirm':if(choice?.selected)accept(choice.selected);break;case'flowDone':finishFlow();break;case'voteDetail':if(choice?.selected){const el=$('vote-detail');el.hidden=!el.hidden;el.innerHTML=cardHTML(choice.selected.v,{large:true})+detailText(choice.selected.v);presentation.invalidate();if(!el.hidden)el.scrollIntoView({block:'nearest'})}break}});
let voteHold=null,voteHoldFired=false,voteStart=null;
function votePreview(el){const o=choice?.opts[+el.dataset.opt];if(o?.v?.kind)tooltipHTML(cardHTML(o.v,{large:true})+detailText(o.v),el.getBoundingClientRect())}
layer.addEventListener('pointerover',e=>{const el=e.target.closest('#vote-collection [data-opt]');if(el&&hoverable.matches&&e.pointerType==='mouse'&&!el.contains(e.relatedTarget))votePreview(el)});
layer.addEventListener('pointerout',e=>{const el=e.target.closest('#vote-collection [data-opt]');if(el&&!el.contains(e.relatedTarget))hideTip()});
layer.addEventListener('pointerdown',e=>{const el=e.target.closest('#vote-collection [data-opt]');if(el&&e.pointerType!=='mouse'){voteHoldFired=false;voteStart={x:e.clientX,y:e.clientY};voteHold=setTimeout(()=>{voteHoldFired=true;votePreview(el)},480)}});
layer.addEventListener('pointermove',e=>{if(voteStart&&Math.hypot(e.clientX-voteStart.x,e.clientY-voteStart.y)>9){clearTimeout(voteHold);voteStart=null}});
for(const type of ['pointerup','pointercancel'])layer.addEventListener(type,()=>{clearTimeout(voteHold);voteStart=null;if(voteHoldFired){setTimeout(hideTip,1500);setTimeout(()=>voteHoldFired=false,500)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalKind==='aux')closeAux()});window.addEventListener('resize',()=>{if(page==='game'){sizeHand();if($('arena'))renderSeats()}if($('log-tree'))drawLogTree()});
show('home');


